// Shared, deterministic rules. The server alone supplies dice in network games.
const COLORS = [
  { id: 'red', name: 'Đỏ', color: '#bd383c', deep: '#731c28', pale: '#f5d1c0', title: 'Quân đỏ' },
  { id: 'green', name: 'Xanh lá', color: '#277951', deep: '#10442d', pale: '#d3e0bd', title: 'Quân xanh lá' },
  { id: 'yellow', name: 'Vàng', color: '#d79c28', deep: '#885512', pale: '#f9e4ad', title: 'Quân vàng' },
  { id: 'blue', name: 'Xanh dương', color: '#246f96', deep: '#143e59', pale: '#c7dee4', title: 'Quân xanh dương' },
];
// 56 unique cells, anticlockwise. Every colour starts 14 cells apart.
const TRACK = [];
for (let y = 0; y <= 6; y++) TRACK.push([6, y]);
for (let x = 5; x >= 0; x--) TRACK.push([x, 6]);
TRACK.push([0, 7], [0, 8]);
for (let x = 1; x <= 6; x++) TRACK.push([x, 8]);
for (let y = 9; y <= 14; y++) TRACK.push([6, y]);
TRACK.push([7, 14], [8, 14]);
for (let y = 13; y >= 8; y--) TRACK.push([8, y]);
for (let x = 9; x <= 14; x++) TRACK.push([x, 8]);
TRACK.push([14, 7], [14, 6]);
for (let x = 13; x >= 8; x--) TRACK.push([x, 6]);
for (let y = 5; y >= 0; y--) TRACK.push([8, y]);
TRACK.push([7, 0]);
const HOME = [
  Array.from({length:6},(_,i)=>[7,i+1]),
  Array.from({length:6},(_,i)=>[i+1,7]),
  Array.from({length:6},(_,i)=>[7,13-i]),
  Array.from({length:6},(_,i)=>[13-i,7]),
];
const PEN = [ [0,0], [0,9], [9,9], [9,0] ];
const SEAT_ORDER = [0,2,1,3];
const RULES = Object.freeze({ version:'vn-one-die-1.0', trackLength:56, entry:[1,6], extraTurn:[1,6], blockJumping:true, home:'exact-next', finish:[6,5,4,3] });
function createGame(players) {
  if (players.length < 2 || players.length > 4 || new Set(players.map(p=>p.color)).size !== players.length) throw new Error('Cần từ 2 đến 4 người với màu khác nhau.');
  if(players.some(p=>!Number.isInteger(p.color)||p.color<0||p.color>3)||new Set(players.map(p=>p.id)).size!==players.length) throw new Error('Người chơi không hợp lệ.');
  return { rules:RULES.version, status:'playing', phase:'roll', players:players.map(p=>({id:p.id,name:p.name,color:p.color,pieces:[-1,-1,-1,-1],forfeited:false})), current:0, dice:null, lastRoll:null, turn:1, winner:null, log:[], event:null, sequence:0 };
}
function globalCell(player,progress) { return progress >= 0 && progress <= 55 ? (player.color*14+progress)%56 : null; }
function settledCount(player) {
  let count=0;
  for(let n=61;n>=58;n--) { if(player.pieces.includes(n)) count++; else break; }
  return count;
}
function isSettled(player,index) { return player.pieces[index] >= 62-settledCount(player); }
function occupant(game,cell,excludeId,excludePiece) {
  for(const p of game.players) {
    if(p.forfeited) continue;
    for(let i=0;i<4;i++) if(!(p.id===excludeId&&i===excludePiece)&&globalCell(p,p.pieces[i])===cell) return {playerId:p.id,piece:i};
  }
  return null;
}
function getMove(game,playerId,piece,die=game.dice) {
  if(game.status!=='playing'||!Number.isInteger(die)||die<1||die>6||!Number.isInteger(piece)||piece<0||piece>3) return null;
  const p=game.players.find(p=>p.id===playerId);
  if(!p||p.forfeited||isSettled(p,piece)) return null;
  const from=p.pieces[piece]; let to; const path=[];
  if(from===-1) {
    if(!RULES.entry.includes(die)) return null;
    to=0; path.push(0);
  } else if(from<55) {
    to=from+die;
    if(to>55) return null; // Must land at the door; no overshoot, no second lap.
    for(let n=from+1;n<=to;n++) path.push(n);
  } else if(from===55) {
    to=55+die;
    if(die>6-settledCount(p)) return null;
    for(let n=56;n<=to;n++) path.push(n);
  } else {
    const nextHome=from-55+1;
    if(die!==nextHome||nextHome>6-settledCount(p)) return null;
    to=from+1; path.push(to);
  }
  let capture=null;
  for(const n of path) {
    if(n>=56) { if(p.pieces.some((v,i)=>i!==piece&&v===n)) return null; }
    else {
      const hit=occupant(game,globalCell(p,n),p.id,piece);
      if(hit) {
        if(n!==to||hit.playerId===p.id) return null;
        capture=hit;
      }
    }
  }
  return {playerId,piece,from,to,path,capture,kind:from===-1?'enter':to>=56?'home':capture?'capture':'move'};
}
function legalMoves(game) {
  if(game.status!=='playing'||game.phase!=='move') return [];
  return [0,1,2,3].map(i=>getMove(game,game.players[game.current].id,i)).filter(Boolean);
}
function addLog(game,text,type='move',color=game.players[game.current]?.color) {
  game.log.unshift({id:++game.sequence,text,type,color,turn:game.turn}); game.log=game.log.slice(0,50);
}
function endTurn(game,die) {
  const bonus=RULES.extraTurn.includes(die);
  if(!bonus) { do { game.current=(game.current+1)%game.players.length; } while(game.players[game.current].forfeited); }
  game.phase='roll'; game.dice=null; game.turn++;
  return bonus;
}
function rollDice(game,playerId,die) {
  if(game.status!=='playing'||game.phase!=='roll'||game.players[game.current].id!==playerId) throw new Error('Chưa đến lượt gieo của bạn.');
  if(!Number.isInteger(die)||die<1||die>6) throw new Error('Xúc xắc không hợp lệ.');
  const p=game.players[game.current];
  game.dice=die; game.lastRoll={value:die,playerId,color:p.color}; game.phase='move';
  addLog(game,`${p.name} gieo được ${die}.`,'roll');
  const moves=legalMoves(game);
  game.event={id:game.sequence,type:'roll',playerId,die,noMoves:moves.length===0};
  if(!moves.length) { addLog(game,`${p.name} không có nước đi hợp lệ.`, 'blocked'); endTurn(game,die); }
  return game;
}
function movePiece(game,playerId,piece) {
  if(game.status!=='playing'||game.phase!=='move'||game.players[game.current].id!==playerId) throw new Error('Chưa đến lượt đi của bạn.');
  const move=getMove(game,playerId,piece);
  if(!move) throw new Error('Quân này không có nước đi hợp lệ.');
  const p=game.players[game.current], die=game.dice;
  if(move.capture) game.players.find(q=>q.id===move.capture.playerId).pieces[move.capture.piece]=-1;
  p.pieces[piece]=move.to;
  const label=move.kind==='enter'?'xuất quân':move.to>=56?`vào chuồng ${move.to-55}`:move.capture?'đá ngựa đối phương':`đi ${die} ô`;
  addLog(game,`${p.name}: ngựa ${piece+1} ${label}.`,move.kind);
  game.event={...move,id:game.sequence,type:'move',die};
  if(settledCount(p)===4) { game.status='finished'; game.phase='finished'; game.winner=p.id; addLog(game,`${p.name} chiến thắng!`,'win'); }
  else game.event.bonus=endTurn(game,die);
  return game;
}
function forfeit(game,playerId) {
  const p=game.players.find(p=>p.id===playerId);
  if(!p||p.forfeited||game.status!=='playing') return game;
  p.forfeited=true; p.pieces=[-1,-1,-1,-1]; addLog(game,`${p.name} đã rời ván.`,'leave',p.color);
  const remaining=game.players.filter(p=>!p.forfeited);
  if(remaining.length<=1) { game.status='finished'; game.phase='finished'; game.winner=remaining[0]?.id??null; }
  else if(game.players[game.current].id===playerId) { do { game.current=(game.current+1)%game.players.length; } while(game.players[game.current].forfeited); game.phase='roll';game.dice=null;game.turn++; }
  game.event={id:game.sequence,type:'leave',playerId};
  return game;
}

// Shared URL validation. No endpoint or session token is taken from an invite URL.
function normalizeHostOrigin(value) {
  if (typeof value !== 'string') throw new Error('Địa chỉ host phải là chuỗi.');
  const input = value.trim();
  if (!input) return '';
  let url;
  try { url = new URL(input); } catch { throw new Error('Địa chỉ host không hợp lệ.'); }
  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password ||
      url.pathname !== '/' || url.search || url.hash || url.hostname.includes('*')) {
    throw new Error('Chỉ nhập origin HTTP/HTTPS của host, không kèm đường dẫn, tài khoản hoặc tham số.');
  }
  return url.origin;
}

function createNetworkConfig(value = '', pageOrigin = '') {
  const origin = normalizeHostOrigin(value);
  if (origin.startsWith('http:') && pageOrigin.startsWith('https:')) {
    throw new Error('Game HTTPS cần kết nối tới host HTTPS.');
  }
  const suffix = origin ? ':' + encodeURIComponent(origin) : '';
  return {
    origin,
    timeout: origin ? 90_000 : 10_000,
    sessionKey: 'horse-session' + suffix,
    resumeKey: 'horse-resume-session' + suffix,
    endpoint(path) {
      if (typeof path !== 'string' || !path.startsWith('/') || path.startsWith('//')) {
        throw new Error('Đường dẫn API không hợp lệ.');
      }
      return origin + '/api' + path;
    },
  };
}

import { existsSync, readFileSync, mkdirSync, openSync, writeFileSync, fsyncSync, closeSync, renameSync } from 'node:fs';
import { dirname } from 'node:path';

function createRoomStore(file,now=()=>Date.now()){
  if(!file)return null;
  function read(){
    if(!existsSync(file))return [];
    const input=JSON.parse(readFileSync(file,'utf8'));
    if(input.schema!==1||!Array.isArray(input.rooms)||input.rooms.length>200)throw new Error('Tệp lưu phòng không hợp lệ. Giữ bản sao trước khi khôi phục.');
    for(const r of input.rooms){
      if(!/^[A-Z2-9]{6}$/.test(r.code)||!Number.isInteger(r.revision)||r.revision<1||![2,3,4].includes(r.capacity)||!Array.isArray(r.members)||r.members.length<1||r.members.length>r.capacity||!Number.isFinite(r.updatedAt))throw new Error('Dữ liệu phòng bị hỏng.');
      for(const p of r.members)if(!/^[a-f0-9]{24}$/.test(p.id)||!/^[a-f0-9]{64}$/.test(p.token)||typeof p.name!=='string'||p.name.length>24||!Number.isInteger(p.color)||p.color<0||p.color>3)throw new Error('Dữ liệu ghế bị hỏng.');
      if(!r.members.some(p=>p.id===r.hostId))throw new Error('Phòng không có chủ.');
      if(r.game){const g=r.game;if(g.rules!=='vn-one-die-1.0'||!Array.isArray(g.players)||g.players.length<2||g.players.length>4||!Number.isInteger(g.current)||g.current<0||g.current>=g.players.length||!['playing','finished'].includes(g.status)||!['roll','move','finished'].includes(g.phase))throw new Error('Ván đã lưu không tương thích.');for(const p of g.players)if(!Array.isArray(p.pieces)||p.pieces.length!==4||p.pieces.some(v=>!Number.isInteger(v)||v< -1||v>61))throw new Error('Vị trí ngựa đã lưu không hợp lệ.');}
    }
    return input.rooms.map(r=>({...r,members:r.members.map(p=>({...p,streams:new Set(),disconnectedAt:now()})),receipts:new Map(r.receipts||[])}));
  }
  function write(rooms){
    const data=JSON.stringify({schema:1,savedAt:now(),rooms:[...rooms.values()].map(r=>({code:r.code,capacity:r.capacity,hostId:r.hostId,revision:r.revision,updatedAt:r.updatedAt,game:r.game,members:r.members.map(({streams,...member})=>member),receipts:[...r.receipts]}))});
    mkdirSync(dirname(file),{recursive:true,mode:0o700});
    const temp=file+'.tmp',fd=openSync(temp,'w',0o600);
    try{writeFileSync(fd,data);fsyncSync(fd);}finally{closeSync(fd);}
    renameSync(temp,file);
  }
  return {read,write};
}

import http from 'node:http';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { resolve, extname } from 'node:path';
import { networkInterfaces } from 'node:os';
import { randomBytes, randomInt, timingSafeEqual } from 'node:crypto';

const ROOT=fileURLToPath(new URL('./dist/',import.meta.url));
const MAX_BODY=8192, MAX_ROOMS=200, ROOM_TTL=24*60*60*1000;
const CONTENT_TYPES={'.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.mjs':'text/javascript; charset=utf-8','.svg':'image/svg+xml','.woff2':'font/woff2','.json':'application/json; charset=utf-8','.webmanifest':'application/manifest+json; charset=utf-8','.js':'text/javascript; charset=utf-8','.png':'image/png'};
// LAN discovery is only a convenience. Restricted hosts may deny this OS call.
function getLanUrls(port,inspect=networkInterfaces) {
  try {
    return [...new Set(Object.values(inspect()).flatMap(addresses=>(addresses||[])
      .filter(address=>address.family==='IPv4'&&!address.internal)
      .map(address=>`http://${address.address}:${port}`)))];
  } catch { return []; }
}
function createApp({dice=()=>randomInt(1,7),now=()=>Date.now(),assets=null,storeFile=null,trustProxy=false,allowedOrigins=[]}={}) {
  const allowed=new Set(allowedOrigins.map(normalizeHostOrigin).filter(Boolean));
  const store=createRoomStore(storeFile,now),rooms=new Map(),limits=new Map();
  const persist=()=>store?.write(rooms);
  const restored=store?.read()||[];
  for(const room of restored)if(now()-room.updatedAt<=ROOM_TTL)rooms.set(room.code,room);
  if(restored.length!==rooms.size)persist();
  function fail(status,message){const e=new Error(message);e.status=status;throw e;}
  function publicRoom(room){return {code:room.code,capacity:room.capacity,hostId:room.hostId,revision:room.revision,phase:room.game?.status??'lobby',members:room.members.map(p=>({id:p.id,name:p.name,color:p.color,ready:p.ready,online:p.streams.size>0,disconnectedAt:p.disconnectedAt})),game:room.game};}
  function send(res,status,data){res.writeHead(status,{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'});res.end(JSON.stringify(data));}
  function emit(room){const data=`event: state\ndata: ${JSON.stringify(publicRoom(room))}\n\n`;for(const member of room.members)for(const res of member.streams) {if(res.writableLength>1024*1024) res.destroy();else res.write(data);} }
  function checkRate(req){const forwarded=trustProxy?String(req.headers['x-forwarded-for']||'').split(',')[0].trim():'';const key=forwarded||req.socket.remoteAddress;const time=now();let e=limits.get(key);if(!e||e.until<time){e={count:0,until:time+60_000};limits.set(key,e);}if(++e.count>180) fail(429,'Bạn thao tác quá nhanh. Chờ một chút rồi thử lại.');}
  async function body(req){let data='';for await(const chunk of req){data+=chunk;if(Buffer.byteLength(data)>MAX_BODY) fail(413,'Yêu cầu quá lớn.');}try {const obj=JSON.parse(data||'{}');if(!obj||Array.isArray(obj)||typeof obj!=='object') throw 0;return obj;}catch{fail(400,'Dữ liệu không hợp lệ.');}}
  function nameOf(value){if(typeof value!=='string')fail(400,'Hãy nhập tên của bạn.');const name=value.normalize('NFC').trim();if(!name||name.length>24||/[\p{C}<>]/u.test(name)) fail(400,'Tên cần có 1–24 ký tự, không chứa ký tự đặc biệt.');return name;}
  function memberOf(req,room){const token=req.headers['x-player-token'];if(typeof token!=='string'||!/^[a-f0-9]{64}$/.test(token))fail(401,'Không có quyền vào ghế này.');const p=room.members.find(p=>timingSafeEqual(Buffer.from(p.token),Buffer.from(token)));if(!p)fail(401,'Phiên chơi đã hết. Hãy tham gia lại.');return p;}
  function newMember(name,color){return {id:randomBytes(12).toString('hex'),token:randomBytes(32).toString('hex'),name,color,ready:false,streams:new Set(),disconnectedAt:now()};}
  function roomOf(code){const room=rooms.get(code);if(!room)fail(404,'Không tìm thấy phòng. Kiểm tra mã và địa chỉ host.');return room;}
  function disconnect(room,p,res){p.streams.delete(res);if(!p.streams.size)p.disconnectedAt=now();emit(room);}
  function removeMember(room,p){if(room.game?.status==='playing')forfeit(room.game,p.id);room.members=room.members.filter(m=>m.id!==p.id);for(const stream of p.streams)stream.end();p.streams.clear();if(!room.members.length){rooms.delete(room.code);persist();return;}if(room.hostId===p.id)room.hostId=room.members[0].id;room.revision++;room.updatedAt=now();persist();emit(room);}
  const server=http.createServer(async(req,res)=>{
    res.setHeader('X-Content-Type-Options','nosniff');
    res.setHeader('Referrer-Policy','no-referrer');
    res.setHeader('X-Frame-Options','SAMEORIGIN');
    res.setHeader('Content-Security-Policy',"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'self'");
    try {
      const url=new URL(req.url,'http://localhost');
      if(url.pathname.startsWith('/api/')) {
        const origin=req.headers.origin;
        res.setHeader('Vary','Origin');
        if(origin){
          let normalized;
          try{normalized=normalizeHostOrigin(origin);}catch{fail(403,'Nguồn truy cập không hợp lệ.');}
          const protocol=(req.socket.encrypted||(trustProxy&&String(req.headers['x-forwarded-proto']||'').split(',')[0].trim()==='https'))?'https':'http';
          if(!normalized||normalized!==origin||(normalized!==`${protocol}://${req.headers.host}`&&!allowed.has(normalized)))fail(403,'Địa chỉ game chưa được host cho phép.');
          res.setHeader('Access-Control-Allow-Origin',origin);
        }
        if(req.method==='OPTIONS'){
          if(!origin)fail(403,'Yêu cầu thiếu Origin.');
          if(!['GET','POST'].includes(req.headers['access-control-request-method']))fail(405,'Phương thức không được hỗ trợ.');
          const headers=String(req.headers['access-control-request-headers']||'').toLowerCase().split(',').map(s=>s.trim()).filter(Boolean);
          if(headers.some(h=>!['content-type','x-player-token'].includes(h)))fail(403,'Header không được phép.');
          res.writeHead(204,{'Access-Control-Allow-Methods':'GET, POST','Access-Control-Allow-Headers':'Content-Type, X-Player-Token','Access-Control-Max-Age':'600','Vary':'Origin, Access-Control-Request-Method, Access-Control-Request-Headers','Cache-Control':'no-store'});res.end();return;
        }
        if(req.method==='POST'&&!String(req.headers['content-type']||'').startsWith('application/json'))fail(415,'Yêu cầu phải có định dạng JSON.');
        if(req.method==='POST')checkRate(req);
        if(url.pathname==='/api/health'&&req.method==='GET') return send(res,200,{ok:true,version:'2.1.1',persistence:!!store});
        if(url.pathname==='/api/rooms'&&req.method==='POST') {
          if(rooms.size>=MAX_ROOMS)fail(503,'Host đã đầy phòng. Hãy thử lại sau.');
          const input=await body(req), name=nameOf(input.name), capacity=input.capacity??4;
          if(![2,3,4].includes(capacity)) fail(400,'Số người chơi phải từ 2 đến 4.');
          const alphabet='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';let code;
          do {code=Array.from({length:6},()=>alphabet[randomInt(alphabet.length)]).join('');}while(rooms.has(code));
          const p=newMember(name,0);p.ready=true;
          const room={code,capacity,hostId:p.id,members:[p],game:null,revision:1,updatedAt:now(),receipts:new Map()};rooms.set(code,room);persist();
          return send(res,201,{token:p.token,playerId:p.id,room:publicRoom(room)});
        }
        const match=url.pathname.match(/^\/api\/rooms\/([A-Z2-9]{6})(?:\/(join|events|action))?$/);
        if(!match)fail(404,'Không tìm thấy địa chỉ này.');
        const room=roomOf(match[1]), endpoint=match[2];
        if(endpoint==='join'&&req.method==='POST') {
          const input=await body(req), name=nameOf(input.name);
          if(room.game)fail(409,'Phòng đã bắt đầu ván. Hãy chờ ván mới.');
          if(room.members.length>=room.capacity)fail(409,'Phòng đã đủ người.');
          const color=SEAT_ORDER.find(c=>!room.members.some(p=>p.color===c));
          const p=newMember(name,color);room.members.push(p);room.revision++;room.updatedAt=now();persist();emit(room);
          return send(res,200,{token:p.token,playerId:p.id,room:publicRoom(room)});
        }
        const player=memberOf(req,room);
        if(!endpoint&&req.method==='GET')return send(res,200,{room:publicRoom(room)});
        if(endpoint==='events'&&req.method==='GET') {
          if(player.streams.size>=3)fail(429,'Ghế này đang mở quá nhiều kết nối.');
          res.writeHead(200,{'Content-Type':'text/event-stream; charset=utf-8','Cache-Control':'no-cache, no-transform','Connection':'keep-alive','X-Accel-Buffering':'no'});res.flushHeaders();
          player.streams.add(res);player.disconnectedAt=null;emit(room);
          const heartbeat=setInterval(()=>res.write(': heartbeat\n\n'),15_000);heartbeat.unref();
          res.on('close',()=>{clearInterval(heartbeat);disconnect(room,player,res);});return;
        }
        if(endpoint==='action'&&req.method==='POST') {
          const input=await body(req);
          if(typeof input.actionId!=='string'||!/^[a-zA-Z0-9-]{8,80}$/.test(input.actionId))fail(400,'Mã thao tác không hợp lệ.');
          const receiptKey=`${player.id}:${input.actionId}`;
          if(room.receipts.has(receiptKey))return send(res,200,{room:publicRoom(room),duplicate:true});
          if(input.revision!==room.revision)return send(res,409,{error:'Bàn cờ vừa thay đổi. Hãy thử lại.',room:publicRoom(room)});
          const isHost=room.hostId===player.id;
          switch(input.type) {
            case 'ready':
              if(room.game)fail(409,'Ván đã bắt đầu.');
              if(typeof input.ready!=='boolean')fail(400,'Trạng thái không hợp lệ.');
              player.ready=input.ready;break;
            case 'start': {
              if(!isHost)fail(403,'Chỉ chủ phòng có thể bắt đầu.');
              if(room.game)fail(409,'Ván đã bắt đầu.');
              if(room.members.length<2)fail(409,'Cần ít nhất 2 người để bắt đầu.');
              if(room.members.some(p=>!p.ready))fail(409,'Chờ mọi người sẵn sàng.');
              if(room.members.some(p=>!p.streams.size))fail(409,'Chờ mọi người kết nối lại.');
              room.game=createGame([...room.members].sort((a,b)=>a.color-b.color));break;
            }
            case 'roll':
              if(!room.game)fail(409,'Ván chưa bắt đầu.');
              if(room.game.status!=='playing'||room.game.phase!=='roll'||room.game.players[room.game.current].id!==player.id)fail(409,'Chưa đến lượt gieo của bạn.');
              rollDice(room.game,player.id,dice());break;
            case 'move':
              if(!room.game)fail(409,'Ván chưa bắt đầu.');
              try{movePiece(room.game,player.id,input.piece);}catch(error){fail(409,error.message);}break;
            case 'rematch':
              if(!isHost)fail(403,'Chỉ chủ phòng có thể mở ván mới.');
              if(room.game?.status!=='finished')fail(409,'Ván hiện tại chưa kết thúc.');
              room.game=null;for(const p of room.members)p.ready=p.id===room.hostId;break;
            case 'remove': {
              if(!isHost)fail(403,'Chỉ chủ phòng có thể bỏ ghế mất kết nối.');
              const target=room.members.find(p=>p.id===input.playerId);
              if(!target||target.id===player.id)fail(400,'Ghế không hợp lệ.');
              if(target.streams.size||!target.disconnectedAt||now()-target.disconnectedAt<60_000)fail(409,'Chỉ bỏ ghế đã mất kết nối ít nhất 60 giây.');
              removeMember(room,target);return send(res,200,{room:publicRoom(room)});
            }
            case 'leave':removeMember(room,player);return send(res,200,{left:true});
            default:fail(400,'Thao tác không hợp lệ.');
          }
          room.revision++;room.updatedAt=now();room.receipts.set(receiptKey,true);
          if(room.receipts.size>200)room.receipts.delete(room.receipts.keys().next().value);
          persist();emit(room);return send(res,200,{room:publicRoom(room)});
        }
        fail(405,'Phương thức không được hỗ trợ.');
      }
      if(req.method!=='GET'&&req.method!=='HEAD')fail(405,'Phương thức không được hỗ trợ.');
      const pathname=decodeURIComponent(url.pathname);
      const asset=pathname==='/'?'index.html':pathname.slice(1);
      if(asset.includes('..')||asset.includes('\\')||asset.includes('\0')||!CONTENT_TYPES[extname(asset)])fail(404,'Không tìm thấy tệp.');
      const file=assets?(Object.hasOwn(assets,asset)?Buffer.from(assets[asset],'base64'):fail(404,'Không tìm thấy tệp.')):await readFile(resolve(ROOT,asset)).catch(()=>fail(404,'Không tìm thấy tệp.'));
      if(asset==='sw.js')res.setHeader('Service-Worker-Allowed','/');
      res.writeHead(200,{'Content-Type':CONTENT_TYPES[extname(asset)],'Cache-Control':'no-cache'});res.end(req.method==='HEAD'?undefined:file);
    } catch(error) {if(!res.headersSent)send(res,error.status??500,{error:error.status?error.message:'Host gặp sự cố. Hãy thử lại.'});else res.end();}
  });
  const cleanup=setInterval(()=>{let changed=false;for(const [code,room]of rooms)if(now()-room.updatedAt>ROOM_TTL&&!room.members.some(p=>p.streams.size)){rooms.delete(code);changed=true;}if(changed)try{persist();}catch(error){console.error('Không lưu được danh sách phòng:',error.message);}for(const [ip,limit]of limits)if(limit.until<now())limits.delete(ip);},60_000);cleanup.unref();
  server.on('close',()=>{clearInterval(cleanup);});
  return {server,rooms};
}

function startHost(options={}) {
  const port=Number(process.env.PORT||3000),host=process.env.HOST||'0.0.0.0';
  const {server}=createApp({...options,storeFile:process.env.ROOMS_FILE||null,trustProxy:process.env.TRUST_PROXY==='1',allowedOrigins:process.env.ALLOWED_ORIGINS?process.env.ALLOWED_ORIGINS.split(','):(options.allowedOrigins||[])});
  server.on('error',e=>{console.error(e.code==='EADDRINUSE'?`Cổng ${port} đang được sử dụng. Hãy đổi PORT.`:e.message);process.exitCode=1;});
  server.listen(port,host,()=>{
    const boundPort=server.address().port;
    console.log(`\n  CÁ NGỰA CLUB\n  Máy host: http://localhost:${boundPort}\n`);
    const lanUrls=getLanUrls(boundPort);
    for(const url of lanUrls)console.log(`  Bạn bè cùng mạng mở: ${url}`);
    if(!lanUrls.length)console.log(`  Chưa tự lấy được địa chỉ LAN. Bạn bè có thể mở http://<IP-của-host>:${boundPort}.`);
    console.log('\n  Tạo phòng và chia sẻ mã 6 ký tự. Nhấn Ctrl+C để dừng.\n');
  });
  const stop=()=>{server.closeAllConnections();server.close(()=>process.exit(0));};
  process.on('SIGINT',stop);process.on('SIGTERM',stop);
  return server;
}

